16	namespace {
17	
18	constexpr int BLOCK_M = 32;   // query rows per block
19	constexpr int BLOCK_N = 64;   // key/value rows per tile
20	constexpr int HEAD_DIM = 128;
21	constexpr int NUM_WARPS = 4;
22	constexpr int NUM_THREADS = NUM_WARPS * 32;
23	constexpr int ROWS_PER_WARP = BLOCK_M / NUM_WARPS;  // 8
24	constexpr int D_PER_LANE = HEAD_DIM / 32;           // 4
25	
26	__device__ __forceinline__ float warp_sum(float v) {
27	#pragma unroll
28	    for (int offset = 16; offset > 0; offset >>= 1)
29	        v += __shfl_xor_sync(0xffffffffu, v, offset);
30	    return v;
31	}
