    const __nv_bfloat16* __restrict__ q,
    const __nv_bfloat16* __restrict__ k,
    const __nv_bfloat16* __restrict__ v,
    __nv_bfloat16* __restrict__ out,
    int seq_len, int num_heads, int kv_heads, float scale, bool causal)
{
    extern __shared__ __nv_bfloat16 smem[];
    __nv_bfloat16* sQ = smem;                                // 32KB (reused as sO)
    __nv_bfloat16* sK = smem + BLOCK_M * HEAD_DIM;           // 16KB
    __nv_bfloat16* sV = smem + (BLOCK_M + BLOCK_N) * HEAD_DIM;  // 16KB

    const int m_tile = blockIdx.x;
    const int bh = blockIdx.y;
    const int b = bh / num_heads, h = bh % num_heads;
    const int kv = (h * kv_heads) / num_heads;
    const int warp = threadIdx.x >> 5;
    const int lane = threadIdx.x & 31;

    const long long qbase = (long long)bh * seq_len * HEAD_DIM;
    const long long kvbase = ((long long)b * kv_heads + kv) * seq_len * HEAD_DIM;

    const int row_lo = m_tile * BLOCK_M;
    const int row_hi = min(row_lo + BLOCK_M, seq_len);       // exclusive
    const int grow_hi = row_hi - 1;                          // last valid row

    // ---- load Q tile into shared, then to registers ----
    cp_async_tile(sQ, q + qbase, BLOCK_M, BLOCK_M * HEAD_DIM / 16, threadIdx.x,
                  row_hi);
    cp_async_commit();
    cp_async_wait0();
    __syncthreads();

    uint32_t qf[K16_STEPS][4];
#pragma unroll
    for (int ks = 0; ks < K16_STEPS; ++ks) {
        const int row0 = warp * 16 + 8 * (lane >> 3 & 1) + (lane & 7);
        const int col0 = ks * 16 + 8 * (lane >> 3 >> 1);
        ldmatrix_x4(qf[ks], sQ + swizzle_off(row0, col0) / 2);
    }

    // ---- accumulator state ----
    float oacc[N8_OUT][4];
    float row_max[2] = {-INFINITY, -INFINITY};
    float row_sum[2] = {0.f, 0.f};
#pragma unroll
    for (int g = 0; g < N8_OUT; ++g)
#pragma unroll
        for (int i = 0; i < 4; ++i) oacc[g][i] = 0.f;

    const int n_tiles = causal ? (grow_hi / BLOCK_N + 1) : (seq_len + BLOCK_N - 1) / BLOCK_N;

    for (int nt = 0; nt < n_tiles; ++nt) {
        // ---- load K/V tile ----
        __syncthreads();  // all warps done reading previous tile
        const int kv_row_hi = causal ? min(grow_hi + 1, (nt + 1) * BLOCK_N) : seq_len;
        const int kv_row_lo = nt * BLOCK_N;
        if (kv_row_lo < kv_row_hi) {
            const int rows = min(BLOCK_N, kv_row_hi - kv_row_lo);
            cp_async_tile(sK, k + kvbase + (long long)kv_row_lo * HEAD_DIM,
                          BLOCK_N, BLOCK_N * HEAD_DIM / 16, threadIdx.x, rows);
            cp_async_tile(sV, v + kvbase + (long long)kv_row_lo * HEAD_DIM,
                          BLOCK_N, BLOCK_N * HEAD_DIM / 16, threadIdx.x, rows);
            cp_async_commit();
        }
        cp_async_wait0();
        __syncthreads();

