14	#include <cuda_bf16.h>
15	#include <math.h>
16	#include <cuda_runtime.h>
17	
18	namespace {
19	
20	constexpr int BLOCK_M = 128;   // query rows per block
21	constexpr int BLOCK_N = 64;    // key/value rows per tile
22	constexpr int HEAD_DIM = 128;
23	constexpr int NUM_WARPS = 8;
24	constexpr int NUM_THREADS = NUM_WARPS * 32;
25	constexpr int N8_PER_TILE = BLOCK_N / 8;      // 8
26	constexpr int K16_STEPS = HEAD_DIM / 16;      // 8  (QK mma k-steps)
27	constexpr int K16_PV = BLOCK_N / 16;          // 4  (PV mma k-steps)
28	constexpr int N8_OUT = HEAD_DIM / 8;          // 16 (PV mma n-groups)
29	constexpr int SMEM_BYTES = (BLOCK_M + BLOCK_N + BLOCK_N) * HEAD_DIM * 2;  // 64KB
30	
31	// ---------------------------------------------------------------------------
32	// Shared memory swizzle: row-major [rows][128] bf16 tile, 256B rows.
33	// Permute the eight 16B granules of each 128B segment by (row & 7) so that
34	// ldmatrix's 8 row addresses (8 consecutive rows, fixed 16B window) hit
35	// distinct banks. Invertible (XOR), preserves 16B alignment.
36	__device__ __forceinline__ int swizzle_off(int row, int col) {
37	    const int byte = row * (HEAD_DIM * 2) + col * 2;
38	    const int gran = (byte >> 4) & 7;
39	    const int sw = (byte >> 4) ^ (row & 7);
40	    return (byte & ~0x70) | (sw << 4) | (byte & 0x0F);
41	}
